<?php
require_once 'config/layout.php';require_once 'config/guidance.php';require_login();$uid=(int)current_user()['id'];
$s=db()->prepare('SELECT a.*,r.instrument_version,r.language_code FROM assessments a LEFT JOIN assessment_responses r ON r.assessment_id=a.id WHERE a.user_id=? ORDER BY a.id DESC');$s->execute([$uid]);$assessments=$s->fetchAll();
$s=db()->prepare('SELECT * FROM recommendation_runs WHERE user_id=? ORDER BY id DESC');$s->execute([$uid]);$runs=$s->fetchAll();page_start('Assessment and recommendation history');
?>
<main id="main" class="wide page-space"><div class="page-intro"><h1>Your interests over time</h1><p>Changes are exploratory observations, not evidence that your ability or personality has changed. Equal scores do not distinguish preferences. Historical assessments without instrument metadata are labelled legacy.</p></div><section class="panel"><h2>Interest profiles</h2><div class="table-scroll" tabindex="0" role="region" aria-label="Assessment history table"><table><caption>Mean response / 5 × 100; 20 = strongly disagree, 100 = strongly agree. These are not percentiles.</caption><thead><tr><th>Date</th><th>Instrument</th><th>Top code</th><?php foreach(['R','I','A','S','E','C'] as $d):?><th><?= $d ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($assessments as $a):$scores=json_array($a['riasec_scores']);?><tr><td><?= e($a['taken_at']) ?></td><td><?= e($a['instrument_version']??'Legacy / unknown') ?> (<?= e($a['language_code']??'?') ?>)</td><td><?= e($a['top_interest']) ?></td><?php foreach(['R','I','A','S','E','C'] as $d):?><td><?= e((string)($scores[$d]??'—')) ?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php if(count($assessments)>1):$new=json_array($assessments[0]['riasec_scores']);$old=json_array($assessments[1]['riasec_scores']);?><h3>Latest change from the previous assessment</h3><p><?php foreach(['R','I','A','S','E','C'] as $d):?><?= $d ?>: <?= sprintf('%+.1f',($new[$d]??0)-($old[$d]??0)) ?> points · <?php endforeach;?></p><?php endif;?><?php if(!$assessments):?><p>No assessment yet. <a href="assessment.php">Start your first assessment</a>.</p><?php endif;?></section><h2>Recommendation history</h2><?php foreach($runs as $run):$payload=json_array($run['payload']);?><details class="panel"><summary><?= e($run['created_at']) ?> · Assessment #<?= (int)$run['assessment_id'] ?> · Profile version #<?= (int)$run['profile_version_id'] ?></summary><p>Method: <?= e($run['method_version']) ?></p><?php $s=db()->prepare('SELECT r.* FROM recommendations r JOIN recommendation_details d ON r.id=d.recommendation_id WHERE d.run_id=? AND r.user_id=? ORDER BY r.match_score DESC');$s->execute([$run['id'],$uid]);foreach($s->fetchAll() as $r):?><p><a href="career-detail.php?id=<?= (int)$r['id'] ?>"><?= e($r['career_title']) ?></a> — <?= e((string)$r['match_score']) ?>%</p><?php endforeach;?><h3>Alternative careers to explore</h3><?php foreach($payload['alternative_suggestions']??[] as $r):?><p><?= e($r['title']) ?> — <?= e($r['explanation']) ?></p><?php endforeach;?></details><?php endforeach;?><?php if(!$runs):?><p class="panel">No versioned recommendations yet. Existing legacy recommendations remain on your dashboard; their original profile and assessment association cannot be reconstructed reliably.</p><?php endif;?></main><?php page_end(); ?>
